// Create TabBar component. active tab index parameter.
function buildTabBar(activeIndex){
  const c = figma.createComponent(); c.name='TabBar'; c.resize(375,74);
  const names=['Home','Explore','Chat','Saved','Profile'];
  const icons=['Icon_Nav_Home_Active','Icon_Nav_Home','Icon_Nav_Explore_Active','Icon_Nav_Explore','Icon_Nav_Chat','Icon_Heart','Icon_Nav_Profile'];
  // add 5 slots horizontally at 75px intervals
  for(let i=0;i<5;i++){
    const slot=figma.createFrame(); slot.name=names[i]; slot.x=i*75; slot.y=0; slot.resize(75,74);
    slot.fills=[]; c.appendChild(slot);
    // active icon type
    const active = (i===activeIndex);
    let iconName;
    if(i===0) iconName= active? 'Icon_Nav_Home_Active':'Icon_Nav_Home';
    else if(i===1) iconName= active? 'Icon_Nav_Explore_Active':'Icon_Nav_Explore';
    else if(i===2) iconName= 'Icon_Nav_Chat';
    else if(i===3) iconName= 'Icon_Heart';
    else iconName= 'Icon_Nav_Profile';
    const ic=inst(iconName); const iw = ic && ic.width || 24;
    if(ic){ ic.x = Math.round((75-iw)/2); ic.y=12; slot.appendChild(ic); }
    const label=T(0,46,75,14,names[i],11, active?'Semi Bold':'Medium', active?VIOLET:GRAY,'CENTER');
    slot.appendChild(label);
  }
  return c;
}
