  function walk(n){
    const t=n.type;
    if(t==='COMPONENT'||t==='COMPONENT_SET'){
      if(n.name in ['Icon_Nav_Home_Active','Icon_Nav_Explore_Active','Icon_Nav_Chat','Icon_Heart_Filled','Icon_Nav_Profile','Icon_Nav_Home','Icon_Nav_Explore','Icon_Heart','Icon_Nav_Chat_Active']) M[n.name]=n;
    }
    if('children' in n){ n.children.forEach(walk); }
  }
  figma.root.children.forEach(walk);
  const need=['Icon_Nav_Home_Active','Icon_Nav_Home','Icon_Nav_Explore_Active','Icon_Nav_Explore','Icon_Nav_Chat','Icon_Nav_Chat_Active','Icon_Heart','Icon_Heart_Filled','Icon_Nav_Profile'];
  const missing=need.filter(k=>!M[k]);
  if(missing.length){ throw new Error('MISSING '+missing.join(',')); }

  const tabs=['Home','Explore','Chat','Saved','Profile'];
  const iconFor={Home:'Icon_Nav_Home_Active',Explore:'Icon_Nav_Explore_Active',Chat:'Icon_Nav_Chat_Active',Saved:'Icon_Heart_Filled',Profile:'Icon_Nav_Profile'};
