  const brand={r:0x68/255,g:0x4D/255,b:0xEC/255};
  const gray={r:0x9C/255,g:0xA3/255,b:0xAF/255};

  const cs = figma.createComponentSet();
  cs.name='TabBar';
  cs.x=0; cs.y=0;

  for(const cur of tabs){
    const comp = figma.createComponent();
    comp.name='current='+cur;
    comp.resize(375,74);
    tabs.forEach(t=>{
      const tab=figma.createFrame();
      tab.name=t; tab.x=xs[t]; tab.y=0; tab.resize(75,74);
      const isCur = (t===cur);
      const iconName = isCur? iconFor[t]: iconDefault[t];
      const iconInst=M[iconName].createInstance();
      iconInst.x=26; iconInst.y=12; iconInst.resize(24,24);
      tab.appendChild(iconInst);
      const label=figma.createText();
      label.characters=t;
      label.fontName={family:'Inter',style:isCur?'Semi Bold':'Regular'};
      label.fontSize=11;
      label.fills=[{type:'SOLID',color:isCur?brand:gray}];
      label.x=0; label.y=46; label.resize(75,14); label.textAlignHorizontal='CENTER';
      tab.appendChild(label);
      comp.appendChild(tab);
    });
    comp.variantProperties={current:cur};
    cs.appendChild(comp);
  }
  console.log('TabBar set built', cs.id);
}
