async function main(){
  const ws=figma.root.children.find(p=>p.name==='03 · Workspace');
  await figma.setCurrentPageAsync(ws);

  // Find icon masters
  const masters={};
  function walk(n){
    if(n.type==='COMPONENT' && /^(Icon_Nav_|Icon_Heart|Icon_Unread)/.test(n.name)) masters[n.name]=n;
    if('children' in n) n.children.forEach(walk);
  }
  figma.root.children.forEach(walk);
  console.log('nav masters:', Object.keys(masters).join(', '));

  // Current TabBar symbol: create 4 more variants as separate components
  const base = ws.children.find(c=>c.type==='COMPONENT' && c.name==='TabBar');
  console.log('base TabBar found:', !!base, base && base.id);

  // Helper to build a tab bar variant given active tab label
  const order=['Home','Explore','Chat','Saved','Profile'];
  const activeIcons={ Home:'Icon_Nav_Home_Active', Explore:'Icon_Nav_Explore_Active' };

  function buildVariant(activeLabel){
    // clone the base component
    const v=base.clone(); // clone component adding to page? clone of component gives component
    // v is a component; rename
    v.name='TabBar/'+activeLabel;
    // For each tab frame, set active icon
    order.forEach(label=>{
      const frame=v.children.find(f=>f.name===label);
      if(!frame) return;
      // remove existing icon instance(text? ) - keep text; swap icon
      const icon=frame.children.find(c=>c.type==='INSTANCE');
      if(icon) icon.remove();
      const isActive=(label===activeLabel);
      let iconName = isActive ? (activeIcons[label]||'Icon_Nav_'+label+'_Active') : (label==='Saved'?'Icon_Heart':'Icon_Nav_'+label);
      // fallback for Chat/Saved/Profile active: use base icon but recolor
      const master=masters[iconName]||masters[label==='Saved'?'Icon_Heart':'Icon_Nav_'+label];
      if(master){
        const inst=master.createInstance();
        inst.x=icon?0:0; inst.y=12; inst.resize(24,24);
        frame.appendChild(inst);
        // center within 75 width
        inst.x=Math.round((75-24)/2);
        if(isActive && !activeIcons[label]){
          // recolor active icon to brand violet
          if(inst.fills){ try{ inst.fills=inst.fills.map(f=>f.type==='SOLID'?{type:'SOLID',color:{r:0.41,g:0.30,b:0.93}}:f); }catch(e){} }
        }
      }
      // label color
      const t=frame.children.find(c=>c.type==='TEXT');
      if(t){ try{ t.fills=[{type:'SOLID',color:isActive?{r:0.41,g:0.30,b:0.93}:{r:0.4,g:0.4,b:0.45}}]; }catch(e){} }
    });
    return v;
  }

  // build 4 variants Explore, Chat, Saved, Profile
  const made=[];
  for(const lbl of ['Explore','Chat','Saved','Profile']){
    const v=buildVariant(lbl);
    v.x = lbl==='Explore'?400:(lbl==='Chat'?800:(lbl==='Saved'?1200:1600));
    v.y=0;
    ws.appendChild(v);
    made.push({lbl,id:v.id});
  }
  console.log('made variants:', JSON.stringify(made));
}
main();

