async function go(){
  const ws=figma.root.children.find(p=>p.name==='03 · Workspace');
  await figma.setCurrentPageAsync(ws);
  const frames={};
  ws.children.forEach(c=>{ if(c.type==='FRAME') frames[c.name]=c; });

  const map={'04_Home':'04_Home','05_Explore':'05_Explore','11_Chat':'11_Chat','13_Saved':'13_Saved','14_Profile':'14_Profile'};
  const tabScreens=['04_Home','05_Explore','11_Chat','13_Saved','14_Profile'];
  // destination for each tab
  const dest={'Home':'04_Home','Explore':'05_Explore','Chat':'11_Chat','Saved':'13_Saved','Profile':'14_Profile'};

  for(const name of tabScreens){
    const f=frames[name];
    if(!f){ console.log('no frame '+name); continue; }
    // find the TabBar instance (could be instance of component set)
    let tabInst=null;
    f.findAll(n=>{ if(n.type==='INSTANCE' && (n.name==='TabBar' || String(n.name).startsWith('TabBar'))){ tabInst=n; } });
    if(!tabInst){ console.log('no tabbar on '+name); continue; }
    // each tab is a frame child of the instance
    for(const tabFrame of tabInst.children){
      if(tabFrame.type!=='FRAME') continue;
      const label=tabFrame.name; // Home / Explore / Chat / Saved / Profile
      const d=dest[label];
      if(!d || !frames[d]){ console.log('no dest for '+label+' on '+name); continue; }
      tabFrame.reactions=[{
        action:{type:'NODE', destinationId:frames[d].id, navigation:'NAVIGATE', transition:{type:'DEFAULT'}},
        trigger:{type:'ON_CLICK'}, enabled:true
      }];
    }
    console.log('tabbar wired on '+name);
  }
  console.log('TABS DONE');
}
