async function go(){
  const ws=figma.root.children.find(p=>p.name==='03 · Workspace');
  await figma.setCurrentPageAsync(ws);

  // Find Home Indicator master anywhere in doc
  let homeIndicator=null;
  (function walk(n){ if(homeIndicator) return; if(n.type==='COMPONENT'&&n.name==='Home Indicator'){homeIndicator=n;return;} if('children'in n)n.children.forEach(walk); })(figma.root);

  // Find TabBar component set & variants
  let set=null; const variants={};
  (function walk(n){
    if(n.type==='COMPONENT_SET'&&n.name==='TabBar'){ set=n; }
    if(set&&n.type==='COMPONENT'&&(set===n.parent)){ variants[n.name.split('/')[1]]=n; }
    if('children'in n)n.children.forEach(walk);
  })(figma.root);

  const target={ '04_Home':'Home', '05_Explore':'Explore', '11_Chat':'Chat', '13_Saved':'Saved', '14_Profile':'Profile' };
  const frames=ws.children.filter(c=>c.type==='FRAME');
  let report=[];
  for(const f of frames){
    // set tab variant
    if(target[f.name] && variants[target[f.name]]){
      f.findAll(n=>{ if(n.type==='INSTANCE' && n.name==='TabBar'){ n.swapComponent(variants[target[f.name]]); report.push(f.name+' tab->'+target[f.name]); } });
    }
    // add home indicator where missing
    if(['05_Explore','06_Property_Details','07_Filter','10_Rent_Booking'].includes(f.name)){
      let hasHome=false;
      f.findAll(n=>{ if(n.type==='INSTANCE' && /Home Indicator/.test(n.name)) hasHome=true; });
      if(!hasHome && homeIndicator){
        const hi=homeIndicator.createInstance();
        hi.name='Home Indicator';
        hi.resizeWithoutConstraints(375,34);
        hi.x=0; hi.y=f.height-34;
        f.appendChild(hi);
        report.push(f.name+' +homeIndicator');
      }
    }
  }
  const homeVariant=variants['Home'];
  report.push('set='+(set?set.id:'none')+' variants='+Object.keys(variants).join(',')+' HomeVariant='+(homeVariant?homeVariant.id:'NONE'));
  throw new Error('DONE '+JSON.stringify(report));
}
