async function go(){
  function recol(node, fill){
    if('fills' in node){
      const f=Array.isArray(node.fills)?node.fills:[];
      if(f.length && f[0].type==='SOLID'){
        node.fills=[{type:'SOLID', color:fill}];
      }
    }
    if('children' in node){ node.children.forEach(c=>recol(c, fill)); }
  }
  const set = figma.root.findOne(n=>n.type==='COMPONENT_SET' && n.name==='TabBar');
  if(!set) throw new Error('no TabBar set');
  const gray={r:0.58,g:0.60,b:0.63}; // ~#949aa6
  const violet={r:0.408,g:0.302,b:0.925}; // #684DEC
  const dark={r:0.11,g:0.11,b:0.13};
  const results=[];
  for(const v of set.children){
    const current = v.name; // 'Home','Explore','Chat','Saved','Profile'
    let tabs=[];
    for(const ch of v.children){
      if(ch.type==='FRAME'){ // each tab frame
        const tabName=ch.name;
        let icon=ch.children.find(c=>c.name.indexOf('Icon_')===0 && c.type==='INSTANCE');
        let label=ch.children.find(c=>c.type==='TEXT');
        const isCurrent = (tabName===current);
        if(icon){
          if(isCurrent){ recol(icon, violet); results.push(v.name+'/'+tabName+' active icon recolored'); }
          else { recol(icon, gray); }
        }
        if(label){
          label.fills=[{type:'SOLID', color: isCurrent? violet : gray}];
        }
      }
    }
  }
  throw new Error('RECOLOR OK '+JSON.stringify(results));
}
