  function setTrigger(node, destName){
    if(!destName || !frames[destName]) { visibleTests.push('MISSING '+destName); return; }
    node.reactions=[{ action:{ type:'NODE', destinationId: frames[destName].id, navigation:'NAVIGATE' }, trigger:{ type:'ON_CLICK', delay:0 } }];
  }

  // Wire tab transitions on each tab screen
  const tabScreens = {
    '04_Home':'Home',
    '05_Explore':'Explore',
    '11_Chat':'Chat',
    '13_Saved':'Saved',
    '14_Profile':'Profile'
  };
  const destMap = { '04_Home':'04_Home','05_Explore':'05_Explore','11_Chat':'11_Chat','13_Saved':'13_Saved','14_Profile':'14_Profile' };

  // Because tab bar is a shared instance, wiring inside instances is complex. Instead wire on the screen frames' TabBar instance tab child frames via mainComponent lookups.
  // Simpler: create tab instance triggers by traversing instance children.
  for(const screenName of Object.keys(tabScreens)){
