    // find TabBar instance
    let tabBar=null;
    screen.findAll(n=>{ if(n.type==='INSTANCE' && n.name==='TabBar') tabBar=n; });
    if(!tabBar){ visibleTests.push(screenName+': no TabBar'); continue; }
    // iterate actual instance children
    tabBar.children.forEach(tabFrame=>{
      const tabName=tabFrame.name;
      const dest = { 'Home':'04_Home','Explore':'05_Explore','Chat':'11_Chat','Saved':'13_Saved','Profile':'14_Profile' }[tabName];
      // set reaction on the tab frame (must be a valid node to add reaction)
      if(dest && tabFrame){
        tabFrame.reactions=[{ action:{type:'NODE', destinationId:frames[dest].id, navigation:'NAVIGATE'}, trigger:{type:'ON_CLICK', delay:0} }];
        visibleTests.push(screenName+': tab '+tabName+' -> '+dest+' (id '+frames[dest].id+')');
      }
    });
