  let count=0;
  for(const sn of tabScreens){
    const f=F[sn];
    let tab=null;
    f.findAll(n=>{ if(n.type==='INSTANCE' && n.name==='TabBar' && !tab) tab=n; });
    if(!tab) continue;
    // tab sub-frames named Home/Explore/Chat/Saved/Profile
    const tabTargets={Home:'04_Home',Explore:'05_Explore',Chat:'11_Chat',Saved:'13_Saved',Profile:'14_Profile'};
    tab.findAll(n=>{
      if(n.type==='FRAME' && tabTargets[n.name]){
        n.interactions=[{trigger:{type:'ON_CLICK'},action:{type:'NODE',destinationId:destMap[tabTargets[n.name]]},enabled:true}];
        count++;
      }
    });
  }
  throw new Error('TABNAV_WIRED='+count);
}
main();

async function main(){
  const ws=figma.root.children.find(p=>p.name==='03 · Workspace');
  await figma.setCurrentPageAsync(ws);
  // Report any top-level nodes that aren't frames or components
  let nonStandard=[];
  for(const c of ws.children){
    if(!['FRAME','COMPONENT','COMPONENT_SET'].includes(c.type)){
      nonStandard.push(c.type+':'+c.name);
    }
  }
  // remove non-standard strays? keep components. Remove leftover vectors/text/rects
  const remove=[];
  for(const c of ws.children){
    if(['TEXT','RECTANGLE','VECTOR','ELLIPSE','GROUP','LINE','ELLIPSE'].includes(c.type)){
      remove.push(c.name+' ('+c.id+')');
      c.remove();
    }
  }
  const frameNames=ws.children.filter(c=>c.type==='FRAME').map(c=>c.name);
  const compSet=ws.children.filter(c=>c.type==='COMPONENT_SET').map(c=>c.name);
  throw new Error('REMOVED='+JSON.stringify(remove)+' FRAMES='+frameNames.length+' COMPSETS='+JSON.stringify(compSet));
}
main();

